    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "We included peer-reviewed human studies of adult (age >18 years ) cardiac arrests (CA) comparing mechanical vs manual compression outcomes in out-of-hospital settings, reported in English, only from North American and European countries with comparable advanced EMS. We excluded case reports, narrative reviews, commentaries, letters, abstracts, mann equin/ animal studies, and studies using mechanical devices other than Autopulse or LUCAS for resuscitation.",
      "reason": "The text explicitly specifies the inclusion criteria regarding population (adults), setting (out-of-hospital), study design (implied by the comparison of mechanical vs manual compression outcomes), and exclusion criteria (case reports, reviews, animal/mannequin studies, specific devices)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "reported in English, only from North American and European countries with comparable advanced EMS.",
      "reason": "The review specifies language (English) and geographic/setting restrictions. While dissemination year is not explicitly stated in the eligibility section, the search strategy (text_14) specifies the date range (January 1-October 1, 2020)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; therefore, this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Our goal in this systematic review was to synthesize studies comparing outcomes from mechanical and manual CPR during OHCA regardless of presenting rhythm.",
      "reason": "The review defines the synthesis groups as mechanical vs. manual CPR during out-of-hospital cardiac arrest (OHCA), which aligns with the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond standard systematic review inclusion/exclusion criteria."
    }
  ],
  "confidence": 95
}

